sys_script.script:
(function executeRule(current, previous) {
    var quantity = parseInt(current.getValue('quantity'), 10);
    if (isNaN(quantity) || quantity <= 0) {
        gs.addErrorMessage('Quantity must be greater than zero.');
        current.setAbortAction(true);
        return;
    }

    var customer = current.getValue('customer');
    if (!customer) {
        gs.addErrorMessage('A customer must be selected for the tyre request.');
        current.setAbortAction(true);
        return;
    }

    var requestType = current.getValue('request_type');
    if (!requestType) {
        gs.addErrorMessage('Request type is required.');
        current.setAbortAction(true);
        return;
    }
})(current, previous);
